  "groups.chat.hideFromList": { tr: "Listemden kaldır", en: "Remove from my list" },
  "groups.chat.hideFromListConfirm": { tr: "Bu topluluk ve şimdiye kadarki mesajlar senin mesaj listenden kaldırılacak. Topluluk ve diğer üyeler etkilenmez; topluluktan ayrılmış olmazsın. Yeni bir mesaj gelirse (sessize almadıysan) topluluk tekrar görünür; istediğin zaman Topluluklar → Üyesi olduklarım sekmesinden geri ekleyebilirsin.", en: "This community and its messages so far will be removed from your message list. The community and other members are unaffected, and you stay a member. If a new message arrives (and the community isn't muted) it will reappear; you can also add it back any time from Communities → Joined." },
  "groups.chat.clearHistoryConfirm": { tr: "Bu topluluğun mesaj geçmişi yalnızca senin görünümünden temizlenecek. Diğer üyelerin mesajları silinmez. Topluluk listende kalır ve yeni mesajları almaya devam edersin.", en: "This community's message history will be cleared from your view only. Other members' messages aren't deleted. The community stays in your list and you keep receiving new messages." },
