  "groups.owner.historyTitle": { tr: "Yeni üyeler önceki mesajları görsün mü?", en: "Can new members see earlier messages?" },
  "groups.owner.historyHelp": { tr: "Yalnızca topluluğun sahibi değiştirebilir. Seçim, topluluktaki tüm üyeler için geçerlidir; kişisel “mesajları temizle” yine yalnızca o kişinin görünümünü etkiler.", en: "Only the community owner can change this. It applies to every member; a personal “clear messages” still only affects that person's own view." },
  "groups.owner.historyHidden": { tr: "Görmesin", en: "Hide earlier messages" },
  "groups.owner.historyHiddenHelp": { tr: "Üye yalnızca katıldığı andan sonraki mesajları görür (varsayılan).", en: "A member sees only messages sent after they joined (default)." },
  "groups.owner.historyVisible": { tr: "Görsün", en: "Show earlier messages" },
  "groups.owner.historyVisibleHelp": { tr: "Üyeler topluluğun tüm geçmiş mesajlarını görür; yeni katılanlar da dahil.", en: "Members see the whole message history, including people who join later." },
  "groups.owner.permissionsTitle": { tr: "Yönetici ve moderatör yetkileri", en: "Admin and moderator permissions" },
  "groups.owner.permissionsHelp": { tr: "Her rol için hangi yetkilerin açık olduğunu sen belirlersin; istediğin zaman verip geri alabilirsin. Değişiklik o roldeki herkes için geçerlidir ve onlara bildirilir.", en: "You decide which permissions each role has and can grant or revoke them any time. Changes apply to everyone in that role and they are notified." },
  "groups.owner.fixedHelp": { tr: "Sahip her zaman tüm yetkilere sahiptir. Sahipliği devretme, topluluğu silme ve yönetici atama yalnızca sahipte kalır; rütbe kuralları (ör. bir yönetici başka yöneticiyi çıkaramaz) yetkiden bağımsız sürer.", en: "The owner always has every permission. Transferring ownership, deleting the community and appointing admins stay with the owner; rank rules (e.g. an admin can't remove another admin) apply regardless of permissions." },
  "groups.owner.resetDefaults": { tr: "Varsayılan yetkilere dön", en: "Reset to default permissions" },
  "groups.owner.save": { tr: "Sahip ayarlarını kaydet", en: "Save owner settings" },
